import { ref, computed, watch, onMounted, onUnmounted } from 'vue';
import { getFXImportStats, importFXRates } from '@/services/api';
import ProgressDialog from './ProgressDialog.vue';
export default {
  name: 'FXImportDialog',
  components: {
    ProgressDialog
  },
  props: {
    modelValue: Boolean
  },
  emits: ['update:modelValue', 'import-completed'],
  setup(props, {
    emit
  }) {
    const dialog = computed({
      get: () => props.modelValue,
      set: value => emit('update:modelValue', value)
    });
    const stats = ref(null);
    const error = ref('');
    const importOption = ref(null);
    const importOptions = [{
      text: 'Import missing instances only',
      value: 'missing'
    }, {
      text: 'Update incomplete instances only',
      value: 'incomplete'
    }, {
      text: 'Import missing and update incomplete',
      value: 'both'
    }];
    const isImporting = ref(false);
    const showProgress = ref(false);
    const progress = ref(0);
    const progressError = ref('');
    const current = ref(0);
    const total = ref(0);
    const fetchStats = async () => {
      try {
        stats.value = await getFXImportStats();
        console.log('Fetched stats:', stats.value);
      } catch (err) {
        error.value = 'Failed to fetch import statistics';
        console.error('Error fetching stats:', err);
      }
    };
    watch(() => dialog.value, newValue => {
      if (newValue) {
        fetchStats();
      }
    });
    const closeDialog = () => {
      dialog.value = false;
      error.value = '';
      importOption.value = null;
    };
    const startImport = async () => {
      isImporting.value = true;
      showProgress.value = true;
      progress.value = 0;
      progressError.value = '';
      current.value = 0;
      total.value = 0;
      try {
        dialog.value = false; // Close the FXImportDialog
        await importFXRates(importOption.value);
      } catch (err) {
        error.value = 'Failed to start import process';
        console.error(err);
        isImporting.value = false;
        showProgress.value = false;
      }
    };
    const handleProgress = event => {
      const data = event.detail;
      if (data.progress) {
        progress.value = data.progress;
        current.value = data.current;
        total.value = data.total;
      }
      if (data.status === 'completed') {
        showProgress.value = false;
        emit('import-completed', data);
        closeDialog();
      }
    };
    onMounted(() => {
      window.addEventListener('fxImportProgress', handleProgress);
    });
    onUnmounted(() => {
      window.removeEventListener('fxImportProgress', handleProgress);
    });
    fetchStats();
    console.log('Import options:', importOptions);
    return {
      dialog,
      stats,
      error,
      importOption,
      importOptions,
      isImporting,
      showProgress,
      progress,
      progressError,
      closeDialog,
      startImport,
      current,
      total
    };
  }
};
